// Create a named pipe (FIFO) in CWD
mode_t fifo_mode = S_IFIFO | 0644;
int status = mknodat(AT_FDCWD,
                     "data/req.pipe",
                     fifo_mode,
                     0);

// Create a character device (Major 1, Minor 2)
// using an open directory file descriptor (log_fd)
dev_t my_dev = makedev(1, 2);
int log_fd = open("/dev/bus", O_RDONLY);

mknodat(log_fd,
        "dev_ctl_01",
        S_IFCHR | 0600,
        my_dev);
close(log_fd);

// Error check: if (status == -1) { perror("mknodat"); }
